--> statement-breakpoint
CREATE TRIGGER salary_tax_slabs_check BEFORE INSERT OR UPDATE ON public.salary_tax_slabs FOR EACH ROW EXECUTE FUNCTION app.check_payroll_row();
--> statement-breakpoint
