-- ── hand-written: the statutory tables every company starts with ────────────────────────────────
-- Only figures read in a primary source on 15 November 2026 (docs/RATES-REVIEW.md and
-- docs/later/step-40.md list them, and what was not found). Checked by Claude, not an
-- accountant. A change in the law is a new dated row, never an edit of an old one; a company adds
-- what is missing here (Balochistan's minimum wage, Islamabad's social security) itself.
CREATE FUNCTION app.seed_payroll_statutory(p_tenant uuid, p_user uuid) RETURNS void
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
BEGIN
    INSERT INTO public.salary_tax_slabs (tenant_id, effective_from, over, up_to, fixed, rate, legal_reference, created_by, updated_by)
    SELECT p_tenant, s.effective_from::date, s.over, s.up_to, s.fixed, s.rate, s.reference, p_user, p_user
    FROM (VALUES
