CREATE FUNCTION app.seed_payroll_statutory_for_new_company() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
BEGIN
  PERFORM app.seed_payroll_statutory(NEW.id, NEW.created_by);
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.seed_payroll_statutory_for_new_company() FROM PUBLIC;
